{"cards": [{"node_code": "N_9d8f65c721c81c8d", "definition": "针对山溪性河流、浅水急流及河流上游段，通过工程措施改善通航条件、稳定航道线形与水深的整治技术体系。", "boundary": "本节点聚焦于上游及山区河流的特殊水文环境。边界在于区分“上游/山溪”与“中下游/河口”（后者水流平缓或受潮汐影响）。若内容涉及上游河段的护岸、丁坝布置或急流段整治，主挂载本节点；若涉及上游河段的单纯疏浚，归入疏浚工程。", "includes": ["山溪性河流航道整治规划与设计", "浅水急流段的水流调节与航道稳定技术", "河流上游河段的护岸、护坡及整治建筑物应用"], "excludes": ["中下游平原河流的整治技术", "河口段的潮汐与泥沙整治技术", "单纯的航道疏浚作业"], "sibling_distinctions": [{"other_code": "N_3937ad5c18f259c3", "rule": "本节点侧重上游及山区河流（单向流、急流）；河口整治侧重河口段（潮汐、泥沙混合、分汊）的特殊环境。"}, {"other_code": "N_85b55cbf9ebb2fb6", "rule": "本节点侧重特定河段（上游/山溪）的整体整治；石滩浅滩整治侧重特定地貌（石滩/浅滩）的局部处理，无论位于哪一河段。"}], "cross_boundary_rule": "若内容涉及上游河段中的石滩整治，主挂载石滩、浅滩整治；若涉及上游河段整体线形调整，主挂载本节点。"}, {"node_code": "N_3937ad5c18f259c3", "definition": "针对河口段受潮汐、泥沙及海陆相互作用影响的航道，通过工程措施稳定航道、改善通航条件的整治技术体系。", "boundary": "本节点聚焦于“河口”这一特殊地理与水文环境。边界在于区分“河口”与“上游/中下游”（无潮汐或潮汐影响微弱）。若内容涉及河口分汊、潮汐航道、河口泥沙运动及整治，主挂载本节点；若涉及河口港口的码头建设，归入港口工程。", "includes": ["河口航道整治规划与设计", "河口潮汐航道的水流调节与泥沙控制", "河口分汊、汊道选择及河口护岸工程"], "excludes": ["上游及山区河流的整治技术", "中下游平原河流的整治技术", "河口港口的码头及堆场工程"], "sibling_distinctions": [{"other_code": "N_9d8f65c721c81c8d", "rule": "本节点侧重河口段（潮汐、泥沙混合）；山溪、浅水急流、河流上游整治侧重上游及山区河流（单向流、急流）。"}, {"other_code": "N_ef0308524e18c731", "rule": "本节点侧重河口整体环境（潮汐、泥沙）的整治；航道淤积整治侧重淤积这一具体问题的处理，无论位于哪一河段。"}], "cross_boundary_rule": "若内容涉及河口段的淤积整治，主挂载航道淤积整治；若涉及河口整体线形与潮汐适应，主挂载本节点。"}, {"node_code": "N_ef0308524e18c731", "definition": "针对航道内泥沙淤积问题，通过工程措施减少淤积、稳定航道水深及线形的整治技术体系。", "boundary": "本节点聚焦于“淤积”这一具体问题的整治。边界在于区分“淤积整治”与“疏浚”（单纯挖泥）及“其他河段整治”（侧重线形或水流）。若内容涉及防淤、减淤、淤积规律分析及针对淤积的整治建筑物，主挂载本节点；若涉及单纯挖泥，归入疏浚工程。", "includes": ["航道淤积规律分析与预测", "防淤、减淤工程措施及整治建筑物设计", "针对淤积问题的航道线形调整与水流调节"], "excludes": ["单纯的航道疏浚挖泥作业", "上游及山区河流的整体整治技术", "河口段的潮汐与泥沙整体整治技术"], "sibling_distinctions": [{"other_code": "N_9d8f65c721c81c8d", "rule": "本节点侧重淤积这一具体问题；山溪、浅水急流、河流上游整治侧重上游河段整体环境。"}, {"other_code": "N_3937ad5c18f259c3", "rule": "本节点侧重淤积这一具体问题；河口整治侧重河口整体环境（潮汐、泥沙）。"}], "cross_boundary_rule": "若内容涉及上游河段的淤积整治，主挂载本节点；若涉及上游河段整体线形调整，主挂载山溪、浅水急流、河流上游整治。"}]}
